    ENF_TYPE_DESC as enf_type_desc,
    AGENCY as agency,
    {{ stg_date('"SETTLEMENT_ENTERED_DATE"') }} as settlement_entered_date,
    {{ stg_float('"FED_PENALTY_ASSESSED_AMT"') }} as fed_penalty_assessed_amt,
